import pytest

from apps.assessments.importers import AssessmentFormImporter
from apps.assessments.models import AssessmentForm
from apps.assessments.services import AssessmentFormService, AssessmentService
from apps.assessments.tests.factories import full_scores, load_example, make_forms
from apps.core.exceptions import InvalidTransition, RuleViolation
from apps.placements.tests.factories import ApprovedPlacementFactory, PeriodFactory

pytestmark = pytest.mark.django_db


def test_import_creates_form_and_criteria_in_order():
    period = PeriodFactory()
    form = AssessmentFormImporter.import_json(period, load_example("example_workplace_form.json"))
    assert form.version == 1
    assert form.is_active
    assert form.weight_percent == 60
    codes = [criterion.code for criterion in form.criteria.all()]
    assert codes == ["W01", "W02", "W03", "W04", "W05", "W06", "W99"]


def test_importing_again_creates_a_new_active_version_and_retires_the_old_one():
    period = PeriodFactory()
    first = AssessmentFormImporter.import_json(period, load_example("example_workplace_form.json"))
    second = AssessmentFormImporter.import_json(period, load_example("example_workplace_form.json"))
    first.refresh_from_db()
    assert (first.version, first.is_active) == (1, False)
    assert (second.version, second.is_active) == (2, True)


@pytest.mark.parametrize(
    "mutation",
    [
        {"criteria": []},
        {"assessor_role": "STUDENT"},
        {"weight_percent": 140},
        {"criteria": [{"code": "X", "name": "Missing max", "type": "SCORE"}]},
        {
            "criteria": [
                {"code": "X", "name": "A", "max_score": 5},
                {"code": "X", "name": "B", "max_score": 5},
            ]
        },
    ],
)
def test_invalid_forms_are_rejected(mutation):
    data = {**load_example("example_workplace_form.json"), **mutation}
    with pytest.raises(RuleViolation):
        AssessmentFormImporter.import_json(PeriodFactory(), data)


def test_missing_keys_are_reported():
    with pytest.raises(RuleViolation) as error:
        AssessmentFormImporter.import_json(PeriodFactory(), {"name": "Only a name"})
    assert "criteria" in error.value.details["missing"]


def test_form_locks_when_an_assessment_is_started_and_new_version_unlocks_editing():
    placement = ApprovedPlacementFactory()
    workplace, _ = make_forms(placement.period)
    data = load_example("example_workplace_form.json")

    AssessmentFormService.replace(  # editable while unused
        form=workplace, name="Renamed", weight_percent=60, criteria=data["criteria"]
    )
    AssessmentService.create_draft(
        actor=placement.workplace_supervisor,
        placement=placement,
        form=AssessmentForm.objects.get(pk=workplace.pk),
        scores=[],
    )
    workplace.refresh_from_db()
    assert workplace.is_locked
    with pytest.raises(InvalidTransition) as error:
        AssessmentFormService.replace(
            form=workplace, name="Again", weight_percent=60, criteria=data["criteria"]
        )
    assert error.value.code == "form_locked"
    with pytest.raises(InvalidTransition) as error:
        AssessmentFormService.patch(form=workplace, name="Still locked")
    assert error.value.code == "form_locked"

    clone = AssessmentFormService.new_version(form=workplace)
    assert clone.version == workplace.version + 1
    assert not clone.is_active
    assert clone.criteria.count() == workplace.criteria.count()
    AssessmentFormService.patch(form=clone, is_active=True)
    workplace.refresh_from_db()
    assert not workplace.is_active


def test_full_scores_helper_builds_a_valid_payload():
    workplace, _ = make_forms(PeriodFactory())
    scores = full_scores(workplace, ratio=0.5)
    assert any(item["score"] == 5 for item in scores)
